  [arith("Un torneo de 3 partidos tiene resultados 8 a 5, 6 a 6 y 4 a 7 para tu equipo. ¿Cuántos puntos hizo tu equipo en total?", "8+6+4", "Se suman los puntos propios de los tres partidos.", " puntos")],
